// Both fetches return ONE item holding the whole response, so the rows are read
// off `.rows` rather than from the item stream. A window with no data comes back
// as {} with no rows key at all, which is why each read is guarded.
const cfg = $('Settings').first().json;
const minImpressions = Number(cfg.min_impressions);
const bestPosition = Number(cfg.best_position);
const worstPosition = Number(cfg.worst_position);
const maxPages = Number(cfg.max_pages);

function rowsOf(nodeName) {
  const j = $(nodeName).first().json || {};
  return Array.isArray(j.rows) ? j.rows : [];
}

const recent = rowsOf('Fetch Recent Queries');
const previous = rowsOf('Fetch Previous Queries');

// Keyed on query AND page, not query alone. The same phrase can rank two of
// your pages, and averaging their positions together would invent a number that
// describes neither of them.
const priorPosition = {};
for (const r of previous) {
  const k = (r.keys || []);
  if (k.length < 2) continue;
  priorPosition[k[0] + '\t' + k[1]] = Number(r.position);
}

const candidates = [];
for (const r of recent) {
  const k = r.keys || [];
  const query = String(k[0] || '');
  const page = String(k[1] || '');
  if (!query || !page) continue;
  const impressions = Number(r.impressions || 0);
  if (impressions < minImpressions) continue;
  // The band is the whole point. Above it you already rank and the fix is
  // different; below it the gap is too big for an on-page change to close.
  const position = Number(r.position || 0);
  if (!(position >= bestPosition && position <= worstPosition)) continue;
  const was = priorPosition[query + '\t' + page];
  candidates.push({
    query: query,
    page_url: page,
    impressions: impressions,
    clicks: Number(r.clicks || 0),
    position: Math.round(position * 10) / 10,
    previous_position: was === undefined ? null : Math.round(was * 10) / 10,
  });
}

// One page owns many wordings of the same keyword. On the test property 34
// surviving rows collapsed to 10 pages, and a single page held 18 of them. Rank
// by row and the run spends every scrape, every model call and every report line
// on that one page, while nine others are never looked at.
const bestByPage = {};
const variantsByPage = {};
for (const c of candidates) {
  variantsByPage[c.page_url] = (variantsByPage[c.page_url] || 0);
  variantsByPage[c.page_url] += 1;
  const held = bestByPage[c.page_url];
  if (!held || c.impressions > held.impressions) bestByPage[c.page_url] = c;
}

const picked = Object.keys(bestByPage)
  .map((p) => bestByPage[p])
  .sort((a, b) => b.impressions - a.impressions)
  .slice(0, maxPages)
  .map((c) => {
    // A page climbing 15 places and a page that fell 7 both sit at position 15.
    // The direction changes the advice, so it travels with the row.
    let movement = 'new to this band';
    if (c.previous_position !== null) {
      const gained = Math.round((c.previous_position - c.position) * 10) / 10;
      if (gained > 0.5) movement = 'up ' + gained + ' places in a month';
      else if (gained < -0.5) movement = 'down ' + Math.abs(gained) + ' places in a month';
      else movement = 'flat for a month';
    }
    return {
      ...c,
      movement: movement,
      other_wordings: variantsByPage[c.page_url] - 1,
    };
  });

// Never return zero items. A Code node that emits nothing ends the branch, so
// the quiet path below would never run and a week with no opportunities would
// look identical to a broken workflow.
if (!picked.length) {
  return [{ json: {
    nothing_in_range: true,
    rows_seen: recent.length,
  } }];
}
return picked.map((c) => ({ json: c }));

// Turns one item per opportunity into one item per URL that needs fetching:
// your page once, then each page ranking above it. Everything downstream joins
// back on position, so the order written here is the order it must stay in.
const cfg = $('Settings').first().json;
const rivalsPerPage = Number(cfg.rivals_per_page);
const domain = String(cfg.site_domain || '')
  .replace(/^https?:\/\//, '')
  .replace(/^www\./, '')
  .replace(/\/+$/, '');
const picked = $('Pick Striking Distance Pages').all().map((x) => x.json);
const items = $input.all();
const out = [];

for (let i = 0; i < items.length; i++) {
  const src = picked[i];
  if (!src || !src.query) continue;

  // Bright Data answers validation errors and rate limits with HTTP 200 and an
  // error body, and neverError swallows the status, so the body is the only
  // place a failure shows up. It also, under parallel load, answers with an
  // empty body and nothing else - seen live on the second of two searches fired
  // together, where the same query returned 8 results a minute later on its own.
  // That case is separated out from a genuine no-results answer, because
  // "nobody ranks for this" and "the search never happened" call for opposite
  // reactions and both used to print the same line.
  let payload = items[i].json.body ?? items[i].json;
  let unreadable = '';
  if (typeof payload === 'string') {
    if (!payload.trim()) {
      unreadable = 'Bright Data returned an empty response - try again';
      payload = {};
    } else {
      try { payload = JSON.parse(payload); }
      catch { unreadable = 'the search response could not be parsed'; payload = {}; }
    }
  }

  const failed = payload.error || payload.error_message;
  const organic = Array.isArray(payload.organic) ? payload.organic : [];

  const above = [];
  let ourLiveRank = 0;
  for (const r of organic) {
    const link = String(r.link || r.url || '');
    if (!link) continue;
    const isUs = link.replace(/^https?:\/\//, '').replace(/^www\./, '').startsWith(domain);
    if (isUs && !ourLiveRank) {
      ourLiveRank = Number(r.rank) || above.length + 1;
      continue;
    }
    if (!ourLiveRank && above.length < rivalsPerPage) {
      above.push({
        rank: Number(r.rank) || above.length + 1,
        title: String(r.title || '').slice(0, 140),
        link: link,
      });
    }
  }

  // Your own page is queued whatever the search did. That keeps this node from
  // ever emitting zero items - the branch above already decided there is work -
  // and a run where the SERP failed still produces a report line saying so
  // rather than dropping the page silently.
  out.push({ json: {
    opportunity: i,
    role: 'ours',
    read_url: src.page_url,
    our_live_rank: ourLiveRank,
    rivals_found: above.length,
    serp_note: failed ? ('search failed: ' + String(failed).slice(0, 120))
      : (unreadable || (organic.length ? '' : 'no organic results came back')),
  } });
  for (const rival of above) {
    out.push({ json: {
      opportunity: i,
      role: 'rival',
      read_url: rival.link,
      rival_rank: rival.rank,
      rival_title: rival.title,
    } });
  }
}

return out;

// The Web Unlocker returns markdown as plain text, so nothing about which URL
// produced it survives into the item. It emits one item per input item in the
// same order, and the HTTP node continues on error rather than dropping the
// item, so the join back to the plan is positional and stays aligned even when
// a fetch fails.
const plan = $('Plan Page Reads').all().map((x) => x.json);
const picked = $('Pick Striking Distance Pages').all().map((x) => x.json);
const items = $input.all();

// A page's heading structure is the comparison. Sending four full articles to a
// model costs more and answers worse: "what do they cover that you do not" is
// literally a list of their headings, and the prose in between is noise.
function outline(raw) {
  const body = String(raw || '');
  if (!body) return { title: '', headings: [], opening: '' };
  const h1 = body.match(/^#\s+(.+)$/m);
  const headings = [];
  const re = /^#{2,3}\s+(.+)$/gm;
  let m;
  while ((m = re.exec(body)) !== null && headings.length < 25) {
    const h = m[1].replace(/[*_`\[\]]/g, '').trim();
    if (h && h.length < 120) headings.push(h);
  }
  const opening = body
    .split('\n')
    .map((s) => s.trim())
    .filter((s) => s.length > 40 && !s.startsWith('#') && !s.startsWith('!') && !s.startsWith('|'))
    .slice(0, 3)
    .join(' ')
    .slice(0, 600);
  return { title: h1 ? h1[1].slice(0, 140) : '', headings: headings, opening: opening };
}

const byOpportunity = {};
for (let i = 0; i < items.length; i++) {
  const step = plan[i];
  if (!step) continue;
  const j = items[i].json || {};
  const failed = j.error || j.error_message;
  const read = outline(failed ? '' : (j.data ?? j.body ?? ''));

  const slot = byOpportunity[step.opportunity] || (byOpportunity[step.opportunity] = {
    ours: null,
    rivals: [],
    our_live_rank: 0,
    rivals_found: 0,
    serp_note: '',
  });

  if (step.role === 'ours') {
    slot.ours = read;
    slot.our_live_rank = step.our_live_rank || 0;
    slot.rivals_found = step.rivals_found || 0;
    slot.serp_note = step.serp_note || '';
  } else if (read.headings.length || read.title) {
    slot.rivals.push({
      rank: step.rival_rank,
      title: step.rival_title || read.title,
      link: step.read_url,
      headings: read.headings.slice(0, 15),
    });
  }
}

const out = [];
for (const key of Object.keys(byOpportunity)) {
  const slot = byOpportunity[key];
  const src = picked[Number(key)];
  if (!src) continue;
  const ours = slot.ours || { title: '', headings: [], opening: '' };
  out.push({ json: {
    ...src,
    our_live_rank: slot.our_live_rank,
    our_title: ours.title,
    our_headings: ours.headings,
    our_opening: ours.opening,
    rivals_above: slot.rivals,
    rivals_read: slot.rivals.length,
    serp_note: slot.serp_note,
  } });
}

// Same rule as the picker: this must never empty the branch.
if (!out.length) {
  return [{ json: { nothing_in_range: true, rows_seen: 0 } }];
}
return out;

