// The Information Extractor does not merge its answer into the item, it
// REPLACES it - every row arrives as {output: {...}} and nothing else. The query
// and the page are gone by this point, so the join back is positional, on the
// same order the extractor received. Matching on a field that no longer exists
// finds nothing and makes every page look unanalysed on a fully green run.
const compared = $('Compare Against Rivals').all().map((x) => x.json);
const items = $input.all();
const stamp = new Date().toISOString().slice(0, 10);
const rows = [];

// The model ignores the schema's enum often enough to plan for - three earlier
// templates drifted on exactly this - so both enums are folded back to the
// values the sheet is allowed to contain.
function normaliseIntent(v) {
  const s = String(v || '').toLowerCase();
  if (s.startsWith('mis') || s.startsWith('no')) return 'mismatch';
  if (s.startsWith('part')) return 'partial';
  return 'matches';
}
function normaliseConfidence(v) {
  const s = String(v || '').toLowerCase();
  if (s.startsWith('h')) return 'high';
  if (s.startsWith('l')) return 'low';
  return 'medium';
}

for (let i = 0; i < items.length; i++) {
  const src = compared[i];
  if (!src || !src.query) continue;
  const j = items[i].json || {};
  const a = (j.output && typeof j.output === 'object') ? j.output : j;

  rows.push({
    checked_on: stamp,
    query: src.query,
    page_url: src.page_url,
    impressions: src.impressions,
    clicks: src.clicks,
    position: src.position,
    previous_position: src.previous_position === null ? '' : src.previous_position,
    movement: src.movement,
    other_wordings: src.other_wordings,
    rivals_above: src.rivals_read || 0,
    top_rival: (src.rivals_above && src.rivals_above[0] && src.rivals_above[0].link) || '',
    missing_topics: String(a.missing_topics || '').slice(0, 500),
    recommended_action: String(a.recommended_action || '').slice(0, 500),
    intent_match: normaliseIntent(a.search_intent_match),
    // Capped, not just normalised. Asked to compare against nothing the model
    // still answered "high confidence" in testing - it had read your page and
    // felt sure about it, which is not the same as being sure about the gap.
    // A row with no rivals behind it must not sit in the sheet looking as
    // trustworthy as one with three.
    confidence: (src.rivals_read || 0) ? normaliseConfidence(a.confidence) : 'low',
  });
}

// A page whose search or fetch failed still belongs in the report. A blank line
// reads as "nothing wrong here", which is the opposite of what happened.
for (const src of compared) {
  if (!src || !src.query) continue;
  if (rows.some((r) => r.query === src.query && r.page_url === src.page_url)) continue;
  rows.push({
    checked_on: stamp,
    query: src.query,
    page_url: src.page_url,
    impressions: src.impressions,
    clicks: src.clicks,
    position: src.position,
    previous_position: src.previous_position === null ? '' : src.previous_position,
    movement: src.movement,
    other_wordings: src.other_wordings,
    rivals_above: 0,
    top_rival: '',
    missing_topics: 'not analysed: ' + (src.serp_note || 'no comparison was possible'),
    recommended_action: 'look at this query by hand',
    intent_match: 'matches',
    confidence: 'low',
  });
}

if (!rows.length) {
  return [{ json: { nothing_in_range: true, rows_seen: 0 } }];
}
return rows.map((r) => ({ json: r }));

// Reads the report rows by name rather than from this node's input, because a
// Google Sheets append sits in between and returns its own confirmation shape.
const rows = $('Build Fix Report').all().map((x) => x.json).filter((r) => r.query);
const cfg = $('Settings').first().json;

if (!rows.length) {
  return [{ json: { message: 'Striking distance check ran and found nothing in range.' } }];
}

const totalImpressions = rows.reduce((s, r) => s + Number(r.impressions || 0), 0);
const lines = [
  '*Striking distance* - ' + rows.length + ' page' + (rows.length === 1 ? '' : 's') +
    ' between position ' + cfg.best_position + ' and ' + cfg.worst_position + ', ' +
    totalImpressions + ' impressions a month between them',
  '',
];

for (const r of rows) {
  const seen = r.rivals_above
    ? r.rivals_above + ' page' + (r.rivals_above === 1 ? '' : 's') + ' above yours read'
    : 'no rival pages could be read';
  lines.push('*' + r.query + '*  position ' + r.position + ', ' + r.movement);
  lines.push('   ' + r.page_url);
  lines.push('   ' + r.impressions + ' impressions, ' + r.clicks + ' clicks - ' + seen);
  if (r.intent_match !== 'matches') {
    lines.push('   _intent ' + r.intent_match + '_');
  }
  lines.push('   Missing: ' + r.missing_topics);
  lines.push('   *Do:* ' + r.recommended_action + '  _(' + r.confidence + ' confidence)_');
  lines.push('');
}

lines.push('Full detail in the sheet. Filters: at least ' + cfg.min_impressions + ' impressions in 28 days.');

return [{ json: { message: lines.join('\n') } }];
